/// <summary>
/// Dispaly Customer Name
/// </summary>
/// <returns>the customer name</returns>
[SysClientCacheDataMethod]
public display custName custName()
{
    return CustTable::find(this.AccountNum).name();
}

    /// <summary>
    /// Validate the record
    /// </summary>
    /// <returns>result of the validation</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();
    
        //Does the customer have a default sales order Site?
        if(!CustTable::find(this.AccountNum).InventSiteId)
        {
            ret = checkFailed("@MET:CustomerSiteMissingWarning");
        }

        return ret;
    }

/// <summary>
/// Does the record exist?
/// </summary>
/// <param name = "_accountNum">Account number</param>
/// <returns>Result</returns>
static boolean exist(METAccountCust _accountNum)
{
    return _accountNum
    && (select firstOnly RecId 
        from METProfileCustTable
        where METProfileCustTable.AccountNum == _accountNum).RecId != 0;
}

    /// <summary>
    /// Does the record exist?
    /// </summary>
    /// <param name = "_accountNum">Account number</param>
    /// <param name = "_forUpdate">For update</param>
    /// <returns>Profile cust table</returns>
    static METProfileCustTable find(METAccountCust _accountNum, boolean _forUpdate = false)
    {
        METProfileCustTable profileCustTable;

        if(_accountNum)
        {
            if(_forUpdate)
            {
                profileCustTable.selectForUpdate(_forUpdate);
            }

            select firstOnly profileCustTable
                where profileCustTable.AccountNum == _accountNum;
        }

        return profileCustTable;
    }

/// <summary>
/// get the customer table
/// </summary>
/// <returns>Customer record</returns>
public CustTable custTable()
{
    return CustTable::find(this.AccountNum);
}
